  "Everything is answering right now. If something stops, it shows up here, and its card shows up on Home.":
    "Op dit moment antwoordt alles. Stopt er iets, dan verschijnt het hier, en verschijnt de kaart ervan op Home.",
  "For those hours Home Assistant doesn't keep the house consumption, so we can't tell how much came from the sun. The band is right all the same.":
    "Voor die uren bewaart Home Assistant het huisverbruik niet, dus is niet te zeggen hoeveel van de zon kwam. De tariefzone klopt wel.",
  "From the sun:": "Van de zon:",
  "From these watts up the unit is on, below it is off. “My air conditioner draws 7 W while off”: with 20 written here, those 7 W stay off. Empty = the entity state decides, as before.":
    "Vanaf deze watts staat de unit aan, eronder uit. „Mijn airco trekt 7 W terwijl hij uit staat”: met 20 hier blijft die 7 W uit. Leeg = de status van de entiteit beslist, zoals voorheen.",
  "Fuel · Range · Engine": "Brandstof · Actieradius · Motor",
