    "Home Assistant heeft de ventilatoropdracht niet aangenomen: probeer het zo nog eens.",
  "Home load": "Huisbelasting",
  "Horizontal swing": "Horizontale lamellen",
  "How much is going through the meter. This is the threshold for those worried about a cut-off: the contract limit lives here. Energy exported to the grid never counts as an overload.":
    "Hoeveel er door de meter gaat. Dit is de drempel voor wie een afschakeling vreest: de contractgrens ligt hier. Energie die naar het net gaat telt nooit als overbelasting.",
  "How much the appliances are drawing, wherever the power comes from. This is the threshold for those with solar who want to know what the house is pulling.":
    "Hoeveel de apparaten vragen, waar de stroom ook vandaan komt. Dit is de drempel voor wie zonnepanelen heeft en wil weten wat het huis trekt.",
  "How the entities look": "Hoe de entiteiten eruitzien",
  "Hybrid motorcycle": "Hybride motorfiets",
