  "No connection to Home Assistant.": "Geen verbinding met Home Assistant.",
  "No entity for the fan switch: set it in Energy → Temperatures and cooling.":
    "Geen entiteit voor de ventilatorschakelaar: zet hem in Energie → Temperaturen en koeling.",
  "No extra reading: the window shows what the appliance has in its own fields.":
    "Geen extra meetwaarden: het venster toont wat in de velden van het apparaat staat.",
