  "Nothing to choose: the appliance has no entities yet.":
    "Niets te kiezen: het apparaat heeft nog geen entiteiten.",
  "On threshold (W)": "Aan-drempel (W)",
  "One tap turns an item off: it stays configured and stops showing in the appliance window — among the readings, the states and the controls at once, because it is the same entity. Everything shows by default, and whatever the integration publishes tomorrow shows up on its own.":
    "Eén tik zet een item uit: het blijft ingesteld en verschijnt niet meer in het apparaatvenster — bij de metingen, de statussen en de bedieningen tegelijk, want het is dezelfde entiteit. Standaard is alles zichtbaar, en wat de integratie morgen publiceert verschijnt vanzelf.",
  "Open right now: ${quali}. Arm anyway?": "Nu open: ${quali}. Toch inschakelen?",
