  "Earthquakes · Weather · Lightning · Pollen · Flights":
    "Aardbevingen · Weer · Bliksem · Pollen · Vluchten",
  "Earthquakes, civil protection warnings, lightning, pollen, thermal comfort and flights overhead: for each one pick the sensor its integration already brought into Home Assistant. No field is required and each one is enough on its own: the page shows only the sources you have. The dashboard calls no service, it reads what is there.":
    "Aardbevingen, waarschuwingen van de civiele bescherming, bliksem, pollen, thermisch comfort en vliegtuigen boven het huis: kies voor elk de sensor die zijn integratie al in Home Assistant heeft gebracht. Geen veld is verplicht en elk volstaat op zich: de pagina toont alleen de bronnen die je hebt. Het dashboard roept geen dienst aan, het leest wat er is.",
