  "Estimated time": "Geschatte tijd",
  Events: "Gebeurtenissen",
  "Every area is a Home Assistant panel of its own, with its own arming modes. The one marked “on the page now” is what the dial and the keypad are commanding: the eye beside another one brings it on screen in its place.":
    "Elk gebied is een eigen Home Assistant-centrale, met eigen inschakelingen. Die met “nu op de pagina” is wat de wijzerplaat en het toetsenbord bedienen: het oog naast een ander haalt dat in zijn plaats op het scherm.",
  "Every field is optional: the card automatically shows what is available. Start, duration, energy and cost of the last cycle are computed automatically from power transitions unless you provide dedicated entities.":
    "Alle velden zijn optioneel: de kaart toont vanzelf wat beschikbaar is. Start, duur, energie en kosten van het laatste programma worden automatisch uit de vermogenswisselingen berekend, tenzij je eigen entiteiten opgeeft.",
  "Every filled box must be a cover.* or switch.* entity.":
    "Elk ingevuld vak moet een cover.*- of switch.*-entiteit zijn.",
  "Every load below is a circle of the Energy flow, under Home, in the order of this list. What you write here is what the flow shows, and the devices you file under it are the ones that appear when you tap the circle.":
    "Elke verbruiker hieronder is een cirkel in de energiestroom onder Thuis, in de volgorde van deze lijst. Wat je hier schrijft, laat de stroom zien, en de apparaten die je eronder zet, verschijnen als je op de cirkel tikt.",
  "Every plant has its own meter, its own solar, its own battery and its own loads. The fields below belong to the selected plant: adding one starts from scratch and leaves what you already configured alone.":
    "Elke installatie heeft een eigen meter, eigen zonnepanelen, een eigen accu en eigen verbruikers. De velden hieronder horen bij de gekozen installatie: er een toevoegen begint bij nul en laat wat je al hebt ingesteld met rust.",
  "Every plant has its own thirteen fields. The one marked “on the page now” is what the Solar thermal page and the Home tile are showing: the eye beside another one brings it on screen in its place.":
    "Elke installatie heeft haar eigen dertien velden. Die met “nu op de pagina” is wat de pagina Zonneboiler en de tegel op Home laten zien: het oog naast een andere haalt die in haar plaats op het scherm.",
  "Everything is here: the window's card shows its room's humidity and says to open as soon as it goes above the threshold.":
    "Alles is er: de kaart van het raam toont de luchtvochtigheid van zijn kamer en zegt te openen zodra die de drempel overschrijdt.",
  "Everything off": "Alles uit",
  "Everything on the repository": "Alles in de repository",
  "Everything the dashboard can do, and whether it shows. The same switch is also at the top of each section's own tab: here they are all together, so you can see what exists without opening them one by one.":
    "Alles wat het dashboard kan, en of het te zien is. Dezelfde schakelaar staat ook bovenaan het tabblad van elke sectie: hier staan ze allemaal bij elkaar, zodat je ziet wat er is zonder ze een voor een te openen.",
