  "Fireplace pump": "Haardpomp",
  "First configure the circles connected to Home. Each circle can use a direct power sensor or automatically sum every child of a load group. Then create the appliances inside each group. Empty or disabled nodes are not forced into the flow.":
    "Stel eerst de cirkels in die met Thuis verbonden zijn. Elke cirkel kan een directe vermogenssensor gebruiken of automatisch alle verbruikers van zijn groep optellen. Maak daarna de apparaten binnen elke groep aan. Lege of uitgeschakelde knopen worden niet in de stroom geforceerd.",
  "First select your lights in the Lights step (or wizard).":
    "Kies eerst je lampen bij de stap Lampen (of in de wizard).",
  Fixed: "Vast",
  "Fixed cycle duration (minutes)": "Vaste programmaduur (minuten)",
  "Flap opened": "Klep geopend",
  "Flightradar24 exposes “current in area”: the count, with the list of flights in the attributes.":
    "Flightradar24 geeft “current in area”: het aantal, met de lijst vluchten in de attributen.",
  "Flights in the area": "Vluchten in de buurt",
