  Food: "Voer",
  "Food level": "Voerniveau",
  "Food running low": "Voer raakt op",
  "For each item enter": "Vul voor elk onderdeel",
  "For every source, Total energy meter is the cumulative Recorder source (normally state_class: total_increasing). It is not a period value: day, month and year are calculated as final Recorder sum minus initial Recorder sum, so meter resets are preserved. Period sensors are optional current-period overrides.":
    "Voor elke bron is de totale energiemeter de cumulatieve Recorder-bron (normaal state_class: total_increasing). Het is geen periodewaarde: dag, maand en jaar worden berekend als de Recorder-eindsom min de beginsom, zodat resets van de meter behouden blijven. Periodesensoren zijn optionele vervangers voor de lopende periode.",
  "For fridge and freezer: shows the temperature strip instead of the power bar.":
    "Voor koelkast en vriezer: toont de temperatuurstrook in plaats van de vermogensbalk.",
  "For lights you only want to see, with no accidental taps: the row stays where it is, the button stops responding.":
    "Voor lampen die je alleen wilt zien, zonder per ongeluk tikken: de rij blijft staan, de knop reageert niet meer.",
  "For sockets that must not be switched off: the fridge, the modem, the freezer. The row stays where it is, the button stops responding.":
    "Voor stopcontacten die niet uit mogen: de koelkast, het modem, de vriezer. De regel blijft staan, de knop reageert niet meer.",
  "For this window only: resting at this percentage or below counts as closed. Empty, the house threshold at the top applies.":
    "Alleen voor dit raam: op dit percentage of lager telt als gesloten. Leeg geldt de huisdrempel bovenaan.",
  "For this window only: when its room's humidity goes above this level, the card says to open it to air out. Empty, the house threshold at the top applies; zero turns the advice off on this window.":
    "Alleen voor dit raam: wanneer de luchtvochtigheid van zijn kamer boven dit niveau komt, zegt de kaart het te openen om te luchten. Leeg geldt de huisdrempel bovenaan; nul zet het advies voor dit raam uit.",
  "For those without a panel: an alarm built with ESPHome, with scripts or with a list of modes. Each button below shows up in the Security section and on the Home tile, next to the panel's own — and when there is no panel, in their place.":
    "Voor wie geen paneel heeft: een alarm gebouwd met ESPHome, met scripts of met een lijst van standen. Elke knop hieronder verschijnt in de sectie Beveiliging en op de Home-tegel, naast die van het paneel — en is er geen paneel, dan in plaats daarvan.",
  "For what recharges instead of being replaced: the wall tablet, a power bank. The two entities are number.* or input_number.*, the ones the device exposes to say where it starts again and where it stops. Leave them empty and this stays a battery like the others.":
    "Voor wat wordt opgeladen in plaats van vervangen: de wandtablet, een powerbank. De twee entiteiten zijn number.* of input_number.*, die het apparaat aanbiedt om te zeggen waar het weer begint en waar het stopt. Laat ze leeg en dit blijft een batterij als alle andere.",
  "Force (ignore rain)": "Forceren (regen negeren)",
  Forest: "Bos",
  "Found next to the appliance — one tap adds them:":
    "Naast het apparaat gevonden — één tik voegt ze toe:",
  "Found next to the player — one tap adds them:":
    "Naast de speler gevonden — één tik voegt ze toe:",
  "Found next to the robot — one tap adds them:": "Naast de robot gevonden — één tik voegt ze toe:",
  "Fountain filter": "Filter van de drinkfontein",
  "Four sensors of your choosing: the ones you actually read to decide, not a house average. The typical one is outdoors, the one you go by for the indoor units. The unit comes from Home Assistant, and a sensor you do not name is a pill that does not show up.":
    "Vier sensoren die jij kiest: degene die je echt afleest om te beslissen, geen gemiddelde van het huis. De typische staat buiten, degene waar je de binnenunits op afstemt. De eenheid komt van Home Assistant, en een sensor die je niet noemt is een tegel die niet verschijnt.",
