  Good: "Goed",
  "Good up to the first, fair up to the second, poor up to the third, bad beyond. The defaults are the norms: the European index bands for particulates and gases, EN 16798-1 for CO₂, the WHO guidelines for monoxide. Change them only if you know why.":
    "Goed tot de eerste, redelijk tot de tweede, slecht tot de derde, zeer slecht daarboven. Standaard zijn het de normen: de banden van de Europese index voor deeltjes en gassen, EN 16798-1 voor CO₂, de WHO-richtlijnen voor koolmonoxide. Verander ze alleen als je weet waarom.",
