  "Leave alone": "Met rust laten",
  "Leave empty if you prefer": "Laat leeg als je dat liever hebt",
  "Leave it as the group icon to follow it; change it to tell this opening from the others.":
    "Laat het gelijk aan het groepspictogram om het te volgen; wijzig het om deze opening van de andere te onderscheiden.",
  "Leave it empty and the circle is the total of the appliances below. Fill it in only if a clamp meter covers the whole line.":
    "Laat het leeg en de cirkel is het totaal van de apparaten hieronder. Vul het alleen in als een stroomtang de hele groep meet.",
  "Leave it empty and the worst reading goes on the cover, which is the right answer when nothing is said. If your station already publishes its own index, put it here: the big number becomes its own, and the substances are read one by one by opening the card. The verdict still belongs to the worst reading — an index saying “good” must not hide a particulate saying “bad”.":
    "Laat het leeg en de slechtste meting komt op de voorkant, wat het juiste antwoord is als je niets zegt. Publiceert je station al een eigen index, zet die dan hier: het grote getal wordt het zijne, en de stoffen lees je één voor één door de kaart te openen. Het oordeel blijft van de slechtste meting — een index die „goed” zegt mag geen fijnstof verbergen die „slecht” zegt.",
  "Leave it empty for something with no due date. With a date it shows up in the agenda, on its day.":
    "Laat leeg voor iets zonder deadline. Met een datum verschijnt het in de agenda, op zijn dag.",
  "Left on the Home Assistant language the dashboard follows the profile of whoever is looking. Picking one pins it for this dashboard, even when Home Assistant speaks another language.":
    "Blijft hij op de taal van Home Assistant, dan volgt het dashboard het profiel van wie er kijkt. Kies je er een, dan ligt hij vast voor dit dashboard, ook als Home Assistant een andere taal spreekt.",
