  "Nobody ticked: the calendar belongs to the house and everyone sees it. Tick one or more and the agenda shows it only to them — the others see the house calendars and their own.":
    "Niemand aangevinkt: de agenda is van het huis en iedereen ziet hem. Vink je één of meer personen aan, dan toont de agenda hem alleen aan hen — de anderen zien de agenda's van het huis en hun eigen.",
