  "Nothing about a pet can be recognised from this device: a bowl, a litter box, a fountain, a microchip door or a collar is needed.":
    "Op dit apparaat is niets van een huisdier te herkennen: er is een voerbak, een kattenbak, een drinkfontein, een kattenluik met microchip of een halsband nodig.",
