  On: "Aan",
  "On / Active / Open (on)": "Aan / Actief / Open (on)",
  "On Home": "Op Home",
  "On battery": "Op accu",
  "On battery · ${carica}%": "Op accu · ${carica} %",
  "On cards show the room temperature big (target below)":
    "Toon op de kaarten de kamertemperatuur groot (doel eronder)",
  "On mains": "Op netstroom",
  "On time": "Op tijd",
  "On which page": "Op welke pagina",
  "On, the radar plays the last hour of rain: you see which way the front is moving, not only where it is now. That is six frames instead of one, so six rounds of tiles: turn it off on a slow connection, or if you prefer a single image.":
    "Aan speelt de radar het laatste uur regen af: je ziet waar het front heen gaat, niet alleen waar het nu is. Dat zijn zes beelden in plaats van één, dus zes rondes tegels: zet het uit bij een trage verbinding, of als je liever één beeld hebt.",
  "On/off control": "Aan/uit-bediening",
  "On/off · Brightness · Colour": "Aan/uit · Helderheid · Kleur",
  "On/off · Consumption · Room by room": "Aan/uit · Verbruik · Kamer voor kamer",
  "One bin per material, and for each the sensor that says when the collection comes: the page answers the evening question — what do I put out tonight — and the Home tile lights up the day before. Whoever has a single calendar, with one event per collection, puts it in the box at the bottom.":
    "Eén bak per materiaal, en voor elk de sensor die zegt wanneer de ophaling komt: de pagina beantwoordt de avondvraag — wat zet ik vanavond buiten — en de tegel op Home licht de dag ervoor op. Wie één kalender heeft, met één afspraak per ophaling, zet die in het vak onderaan.",
  "One room at a time · Scenes · Sensors": "Eén kamer tegelijk · Scènes · Sensoren",
  "One single tile": "Eén enkele tegel",
  "One step, and you will never be asked again: open github.com/login/device and type this code.":
    "Eén stap, en het wordt je nooit meer gevraagd: open github.com/login/device en typ deze code.",
  "One tile per plant": "Eén per installatie",
  "One window can carry all three: fill in the boxes you have, the box tells the type.":
    "Aan één raam kunnen alle drie zitten: vul de vakjes in die je hebt, het vakje zegt het type.",
  "Only daily sensors or Recorder deltas from cumulative total meters are counted. Lifetime values are never added directly.":
    "Alleen dagsensoren of Recorder-verschillen van cumulatieve totaalmeters worden geteld. Totaalstanden worden nooit rechtstreeks opgeteld.",
  "Only if you already have a helper measuring the period. Without one, the period comes from the total meter.":
    "Alleen als je al een helper hebt die de periode meet. Zonder helper komt de periode uit de totaalmeter.",
  "Only needed when the shutter is driven by two relays — one that sends it up, one that sends it down — like a Shelly left in switch mode: then “Close” switches this one on, and “Stop” switches both off. With a real cover.* leave it empty.":
    "Alleen nodig als het rolluik door twee relais wordt bediend — één omhoog, één omlaag — zoals een Shelly die in schakelaarstand staat: dan schakelt “Sluiten” deze in en zet “Stop” ze allebei uit. Bij een echte cover.* laat je dit leeg.",
  "Only rooms containing a light are shown. Edit opens all light fields, not a browser prompt. The pills say what each light can do — RGB, tunable white, dimmer or plain on/off — and that is what drives the controls in the popup.":
    "Alleen kamers met een lamp worden getoond. Bewerken opent alle velden van de lamp, geen browservenster. De labels tonen wat elke lamp kan — RGB, instelbaar wit, dimmer of gewoon aan/uit — en daar richten de bedieningselementen in het venster zich naar.",
  "Only the modes the panel actually accepts are listed. Removing one hides it from the section and changes nothing about what the panel can do; disarm always stays.":
    "Alleen de standen die de centrale echt aanneemt staan hier. Er een weghalen verbergt hem in de sectie en verandert niets aan wat de centrale kan; uitschakelen blijft altijd staan.",
  "Only with the soil below (%)": "Alleen als de bodem onder (%) zit",
  Open: "Open",
  "Open (as before)": "Openen (zoals eerst)",
  "Open the menu": "Menu openen",
  "⚪ Empty section — add an entity below to show it":
    "⚪ Lege sectie — voeg hieronder een entiteit toe om hem te tonen",
  "You haven't saved": "Je hebt niet opgeslagen",
  "You entered entities in this section without saving them. If you leave now, they will be lost.":
    "Je hebt entiteiten in deze sectie ingevoerd zonder ze op te slaan. Als je nu weggaat, gaan ze verloren.",
  "Save and continue": "Opslaan en doorgaan",
  "Leave without saving": "Verlaten zonder opslaan",
  "Stay here": "Hier blijven",
  "Nobody home": "Niemand thuis",
  "Big buttons: a dashboard action or any entity (a scene, a script, a button). For each one the name on the tablet, the line below and the drawing.":
    "Grote knoppen: een actie van het dashboard of een willekeurige entiteit (een scène, een script, een knop). Voor elk de naam op de tablet, de regel eronder en de tekening.",
  "Full config": "Volledige configuratie",
  "On, a light added to the room in the source dashboard shows up by itself. Off, the slots are chosen here: any entity or action, with the name and drawing you want.":
    "Aan: een lamp die in het brondashboard aan de kamer wordt toegevoegd, verschijnt vanzelf. Uit: de plaatsen kies je hier – elke entiteit of actie, met de naam en tekening die je wilt.",
  "Slots of your own: in each one any Home Assistant entity — a light, a socket, a lock, a sensor — or a dashboard action, with the name and drawing you want.":
    "Plaatsen helemaal van jou: in elk een willekeurige Home Assistant-entiteit – een lamp, een stopcontact, een slot, een sensor – of een actie van het dashboard, met de naam en tekening die je wilt.",
  "A dehumidifier is not a thermostat: pick its humidifier entity and the Climate page gives it a card of its own, with the current humidity, the target, the modes, the fan and the tank-full warning. The other fields fill themselves in when you save.":
    "Een luchtontvochtiger is geen thermostaat: kies zijn humidifier-entiteit en de Klimaatpagina geeft hem een eigen kaart, met de huidige luchtvochtigheid, het doel, de modi, de ventilator en de waarschuwing voor een volle tank. De andere velden vullen zich vanzelf bij het opslaan.",
  "Add a dehumidifier": "Luchtontvochtiger toevoegen",
  "Alongside (filled in automatically on save)": "Ernaast (wordt bij opslaan automatisch ingevuld)",
