  Shutters: "Rolluiken",
  "Shutters and curtains show up on the 🪟 Windows page, grouped by floor and room. Every row accepts a cover.* entity — with position and percentages — or a switch.* relay: one when switching it on keeps the shutter up, two when one relay sends it up and another sends it down, like a Shelly in switch mode. When the window opens by hand — shutters, blinds, a handle — leave the command boxes empty and fill in the contact sensor alone: the card still draws it and says whether it is open.":
    "Rolluiken en gordijnen verschijnen op de pagina 🪟 Ramen, gegroepeerd per verdieping en kamer. Elke rij accepteert een cover.*-entiteit — met positie en percentages — of een switch.*-relais: één als het rolluik bij inschakelen omhoog blijft, twee als het ene omhoog en het andere omlaag stuurt, zoals een Shelly in schakelaarstand. Gaat het raam met de hand open — luiken, blinden, een kruk — laat de bedieningsvakken dan leeg en vul alleen de openingssensor in: de kaart wordt gewoon getekend en zegt of het open staat.",
  "Shutters · Curtains · Contact sensors": "Rolluiken · Gordijnen · Openingssensoren",
  "Sign path timeout": "Time-out bij het ondertekenen van het pad",
  "Simple alternative to the duration entity.": "Eenvoudig alternatief voor de duurentiteit.",
  "Since last charge": "Sinds de laatste lading",
  "Since last restart": "Sinds de laatste herstart",
