  "Small pool": "Klein zwembad",
  "Smart thermostats publish the heating mode on a separate entity: TADO has Home and Away, others add Holiday or Boost. The card shows it, and if the entity is a select or an input_select you can change it right there.":
    "Slimme thermostaten publiceren de verwarmingsmodus op een aparte entiteit: TADO heeft Thuis en Afwezig, andere voegen Vakantie of Boost toe. De kaart laat hem zien, en als de entiteit een select of een input_select is verander je hem daar meteen.",
  "SmartThings, Sonos, Chromecast, AirPlay… pick the device and the player arrives ready-made: its entity, the controls the integration publishes next to it — a TV's power switch, the input dropdown — and its readings. Or, below, one field at a time.":
    "SmartThings, Sonos, Chromecast, AirPlay… kies het apparaat en de speler komt kant-en-klaar: zijn entiteit, de bediening ernaast — de aan-uitschakelaar van een tv, de bronkeuze — en zijn metingen. Of hieronder, veld voor veld.",
