  "Too much time has passed: start over.": "Er is te veel tijd verstreken: begin opnieuw.",
  "After signing in the browser tries to open the E.ON app and fails: open the developer tools (F12), Console tab, and copy the line that contains “code=”.":
    "Na het aanmelden probeert de browser de E.ON-app te openen en lukt dat niet: open de ontwikkelaarstools (F12), tabblad Console, en kopieer de regel met „code=”.",
  "Your customer-area credentials. They go through GdAHome, at home, only to sign in: the password is not saved, only the supplier's access tokens are kept.":
    "Je inloggegevens van de klantenzone. Ze gaan thuis via GdAHome, alleen om aan te melden: het wachtwoord wordt niet bewaard, alleen de toegangstokens van de leverancier.",
  "Still reading the Recorder statistics": "De Recorder-statistieken worden nog gelezen",
