  "Total AC draw": "Totale AC-opname",
  "Total charged energy": "Totaal geladen energie",
  "Total consumption": "Totaal verbruik",
  "Total discharged energy": "Totaal ontladen energie",
  "Total energy": "Totale energie",
  "Total energy for history and Report": "Totale energie voor de geschiedenis en het rapport",
