  Trains: "Treinen",
  Tree: "Bomen",
  "Tree (optional)": "Bomen (optioneel)",
  Trend: "Verloop",
  "Try asking": "Vraag bijvoorbeeld",
  "Try again from «Mine».": "Probeer het opnieuw via «Mijne».",
  "Try the controls": "Probeer de bediening",
  "Tumble dryer": "Wasdroger",
  Tumbling: "Kreukbeveiliging",
  Turban: "Tulband",
  Turbo: "Turbo",
  "Turn all lights off": "Alle lampen uitschakelen",
  "Turn all off": "Alles uitschakelen",
  "Turn all on": "Alles inschakelen",
  "Turn everything off": "Alles uitzetten",
  "Turn everything on": "Alles aanzetten",
  "Turn it off to open on the first tap: whoever opens their own front door ten times a day knows the confirmation by heart. A PIN is not a confirmation and stays: a protected door keeps asking for it.":
    "Zet het uit om bij de eerste tik te openen: wie zijn eigen voordeur tien keer per dag opent, kent de bevestiging uit het hoofd. Een pincode is geen bevestiging en blijft: een beveiligde deur vraagt er nog steeds om.",
  "Turn off": "Uitschakelen",
  "Turn on": "Inschakelen",
  "Turn on or off": "In- of uitschakelen",
  "Turn on/off": "Aan/uit",
  "Turn the boiler on or off": "De ketel aan- of uitzetten",
  "Turning them on and off": "Aan- en uitzetten",
  Tuxedo: "Smoking",
  "Two shots of the same car: the dashboard shows the plugged-in one while it charges and the other one the rest of the time. The first is enough — without the second it simply stays.":
    "Twee foto's van dezelfde auto: het dashboard toont die met de stekker erin tijdens het laden en de andere de rest van de tijd. De eerste volstaat — zonder de tweede blijft die gewoon staan.",
  "Two weeks that repeat, written by hand: tap a day and pick what goes out. No sensor and no Home Assistant calendar needed — the page and the Home tile read this exactly as they would read an integration. A material that already has its own sensor above is not repeated: the sensor wins.":
    "Twee weken die zich herhalen, met de hand geschreven: tik op een dag en kies wat er buiten gaat. Geen sensor en geen Home Assistant-kalender nodig — de pagina en de Home-tegel lezen dit net zoals ze een integratie zouden lezen. Een fractie die hierboven al zijn eigen sensor heeft, wordt niet herhaald: de sensor wint.",
  Type: "Type",
  "Type / artwork": "Type / illustratie",
  "Type at least two letters: it searches every tab at once.":
    "Typ minstens twee letters: er wordt in alle tabbladen tegelijk gezocht.",
  "Type the code…": "Typ de code…",
