  "${quanti} m³ today": "${quanti} m³ vandaag",
  "Water and gas": "Water en gas",
  "Add meter": "Meter toevoegen",
  "What you call it: this is what the page reads.": "Hoe jij hem noemt: dit staat op de pagina.",
  "Water meter": "Watermeter",
  "Gas meter": "Gasmeter",
  "New meter": "Nieuwe meter",
  "Meter saved": "Meter opgeslagen",
  "Unnamed meter": "Meter zonder naam",
  "Meters · Today and this month": "Meters · Vandaag en deze maand",
  "What it measures": "Wat hij meet",
  "Time to buy more": "Tijd om bij te kopen",
  "Buy more below": "Bijkopen onder",
  "and nobody is home": "en er is niemand thuis",
  "Sensor entity": "Sensorentiteit",
  "Until you pick the entity this meter is nowhere: not on the page, not on the Home tile.":
    "Zolang je geen entiteit kiest is deze meter nergens: niet op de pagina, niet op de tegel van Home.",
  "Meters give today, yesterday and the month. Flow above zero for three hours without stopping is a leak, and the page says so in red. Pressure has its ideal range, and the softener salt is counted in days.":
    "Meters geven vandaag, gisteren en de maand. Een doorstroming boven nul drie uur lang zonder te stoppen is een lek, en de pagina zegt het in het rood. De druk heeft zijn ideale bereik, en het zout van de ontharder wordt in dagen geteld.",
  "The meters of the house: water, gas, and what the plumbing says. Each row is a sensor — the entity, the name you want, the drawing and what it measures — and the Water and gas page shows today, yesterday and the month, the pressure within its range, and water that never stops flowing.":
    "De meters van het huis: water, gas en wat de leidingen vertellen. Elke rij is een sensor — de entiteit, de naam die je wilt, de tekening en wat hij meet — en de pagina Water en gas toont vandaag, gisteren en de maand, de druk binnen zijn bereik, en water dat nooit ophoudt met stromen.",
  "Ideal from (bar)": "Ideaal vanaf (bar)",
  "Ideal up to (bar)": "Ideaal tot (bar)",
  "Yesterday ${quanto}": "Gisteren ${quanto}",
  "The meter that counts (total or total_increasing), or the pressure, flow or salt sensor.":
    "De meter die telt (total of total_increasing), of de sensor voor druk, doorstroming of zout.",
  "Last month ${quanto}": "Vorige maand ${quanto}",
  "On the bill it is the conversion coefficient: about 10.7 for methane. It lets gas and electricity be compared in the same unit.":
    "Op de rekening is het de omrekeningsfactor: ongeveer 10,7 voor aardgas. Zo kunnen gas en stroom in dezelfde eenheid worden vergeleken.",
  "kWh per m³ (from the bill)": "kWh per m³ (van de rekening)",
  "The range a home's water should stay in: 2 to 4 bar for almost all of them. Outside it, the page turns amber.":
    "Het bereik waarbinnen het water in huis moet blijven: 2 tot 4 bar voor bijna alle huizen. Daarbuiten kleurt de pagina amber.",
  "Never still in 24 hours": "In 24 uur nooit stil",
  "In the same unit as the sensor: percent or kilograms. The page counts the days left, at the pace of the last few days.":
    "In dezelfde eenheid als de sensor: procent of kilo. De pagina telt de resterende dagen, in het tempo van de laatste dagen.",
  "No meter configured": "Geen meter ingesteld",
  "Water flow": "Waterdoorstroming",
