    "Neem de ${quante} bodemsensoren die Home Assistant heeft gevonden",
  "The plants at home, one per row: the soil moisture sensor, the name, the drawing, and the temperature if there is one. The Plant care page says which need watering, which are waiting for rain and when the others will be due.":
    "De planten in huis, één per rij: de sensor voor bodemvochtigheid, de naam, de tekening en, als die er is, de temperatuur. De pagina Planten zegt welke water nodig hebben, welke op regen wachten en wanneer de andere aan de beurt zijn.",
  "The rain will see to it": "De regen doet het werk",
  "The sensor stuck in the soil, in percent: Ecowitt, Tuya, Xiaomi.":
    "De sensor in de grond, in procent: Ecowitt, Tuya, Xiaomi.",
