    "Zolang je geen entiteit kiest is deze plant nergens: niet op de pagina, niet op de tegel van Home.",
  Waiting: "Wacht",
  "watered just now": "net water gegeven",
  "When the soil is dry but the home weather forecasts rain in the next hours, the plant waits instead of asking for water. Only for those the rain really reaches.":
    "Als de grond droog is maar het weer van het huis regen voorspelt in de komende uren, wacht de plant in plaats van om water te vragen. Alleen voor planten waar de regen echt bij komt.",
