  "shutters open": "rolluiken open",
  "Under the weather, open doors and open windows are two pills. By default the class Home Assistant gives the contact decides; pick here when it is not the right one.":
    "Onder het weer zijn open deuren en open ramen twee pillen. Standaard beslist de klasse die Home Assistant het contact geeft; kies hier als die niet klopt.",
  "If the camera already has its own integration in Home Assistant — Reolink, Tapo, Hikvision — the entity is already there: pick it in the field above, and the video goes through it.":
    "Heeft de camera al een eigen integratie in Home Assistant — Reolink, Tapo, Hikvision —, dan is de entiteit er al: kies die in het veld hierboven, en de video loopt daarlangs.",
  "The stream name only works with the dashboard opened outside Home Assistant: in here it cannot be reached, and the camera goes through its entity.":
    "De streamnaam werkt alleen als het dashboard buiten Home Assistant is geopend: hierbinnen is hij niet bereikbaar, en de camera loopt via zijn entiteit.",
  "HLS: skipped, Home Assistant declares no stream for this camera":
    "HLS: overgeslagen, Home Assistant meldt geen stream voor deze camera",
  "WebRTC: the go2rtc stream name only works with the dashboard opened outside Home Assistant — in here the camera goes through its entity":
    "WebRTC: de go2rtc-streamnaam werkt alleen als het dashboard buiten Home Assistant is geopend — hierbinnen loopt de camera via zijn entiteit",
  "WebRTC: tried first with its full time, the video did not arrive":
    "WebRTC: eerst geprobeerd met al zijn tijd, de video kwam niet aan",
  Bypass: "Overbruggen",
