  "Add pack": "Pakket toevoegen",
  "An entity, or the number printed on the pack label with its unit. With every pack's capacity the overall charge is weighted by energy, and the page says when it will be full or empty.":
    "Een entiteit, of het getal op het etiket van het pakket met de eenheid. Met de capaciteit van elk pakket wordt de totale lading naar energie gewogen, en zegt de pagina wanneer het vol of leeg is.",
