  health: "gezondheid",
  "ideal below ${soglia}": "ideaal onder ${soglia}",
  "In Ah, Wh or kWh. Left empty, it is worked out from the charge and the capacity.":
    "In Ah, Wh of kWh. Leeg gelaten wordt het berekend uit de lading en de capaciteit.",
  "It recognises JK, JBD and Daly BMS and Huawei LUNA2000 batteries from their entity names and groups them by prefix. It puts them here as rows, once: from then on they are yours.":
    "Herkent JK-, JBD- en Daly-BMS en Huawei LUNA2000-accu's aan de namen van hun entiteiten en groepeert ze per voorvoegsel. Zet ze hier één keer als rijen: daarna zijn ze van jou.",
  "Optional. A battery that talks through the inverter — like the Huawei LUNA2000 with the Huawei Solar integration — has no BMS to choose: state of charge, power and energy go in Energy, “Flows & entities” tab, in the “Battery · charge” and “Battery · discharge” boxes. This tab is only for seeing the packs, or the modules, one by one.":
    "Optioneel. Een accu die via de omvormer communiceert — zoals de Huawei LUNA2000 met de integratie Huawei Solar — heeft geen BMS om te kiezen: laadtoestand, vermogen en energie horen in Energie, tabblad ‘Stromen en entiteiten’, in de vakken ‘Battery · charge’ en ‘Battery · discharge’. Dit tabblad is alleen om de packs, of de modules, één voor één te zien.",
  "max ${cifre(pacco.massima.volt, 3)} V · cell ${pacco.massima.numero}":
    "max ${cifre(pacco.massima.volt, 3)} V · cel ${pacco.massima.numero}",
  "min ${cifre(pacco.minima.volt, 3)} V · cell ${pacco.minima.numero}":
    "min ${cifre(pacco.minima.volt, 3)} V · cel ${pacco.minima.numero}",
  "MOS temperature": "MOS-temperatuur",
  "needs balancing": "te balanceren",
  "Needs balancing": "Te balanceren",
  "Needs balancing above (mV)": "Te balanceren boven (mV)",
  "New pack": "Nieuw pakket",
  "No battery pack": "Geen batterijpakket",
  "No battery pack configured": "Geen batterijpakket ingesteld",
  "No cells found": "Geen cellen gevonden",
  "No pack answering": "Geen pakket reageert",
  "No reading": "Geen meting",
  "One cell voltage per line, in cell order. You can paste them all at once, commas work too; “Find the cells” takes them from Home Assistant using the prefix of the pack's other entities.":
    "Eén celspanning per regel, in de volgorde van de cellen. Je kunt ze allemaal tegelijk plakken, ook gescheiden door komma's; „Cellen zoeken” haalt ze uit Home Assistant met het voorvoegsel van de andere entiteiten van het pakket.",
  "Optional: if the BMS does not publish it, the imbalance is worked out from the cells.":
    "Optioneel: als het BMS het niet publiceert, wordt de onbalans berekend uit de cellen.",
  "Other BMS": "Ander BMS",
  "Pack 1": "Pakket 1",
  "Pack saved": "Pakket opgeslagen",
  "Current sign": "Teken van de stroom",
  "Positive when charging (JK, JBD, Daly)": "Positief bij laden (JK, JBD, Daly)",
  "Negative when charging": "Negatief bij laden",
  "With the sign the BMS uses: if it writes it negative while charging, pick that in “Current sign”.":
    "Met het teken dat het BMS gebruikt: schrijft het de stroom negatief bij laden, kies dat bij „Teken van de stroom”.",
  "If the page says “Discharging” while the battery is charging, your BMS writes the current the other way round: pick “Negative when charging”.":
    "Als de pagina „Ontladen” zegt terwijl de batterij laadt, schrijft je BMS de stroom andersom: kies „Negatief bij laden”.",
  "Remaining energy": "Resterende energie",
  "Save pack": "Pakket opslaan",
  "State of charge (SoC)": "Laadtoestand (SoC)",
  "State of health (SoH)": "Gezondheidstoestand (SoH)",
  "Take the ${quanti} packs Home Assistant found":
    "Neem de ${quanti} pakketten die Home Assistant heeft gevonden",
  "The pack's charge percentage: without it the pack does not show.":
    "Het laadpercentage van het pakket: zonder dat wordt het pakket niet getoond.",
  "The storage packs and their BMS: they show in the Batteries tab of Energy and on the Battery storage tile in Home. One pack per row: its entity is the state of charge, and inside are the others — health, voltages, currents, temperatures, cycles, capacity and every single cell.":
    "De pakketten van de opslag en hun BMS: ze staan in het tabblad Batterijen van Energie en op de tegel Batterijopslag op Home. Eén pakket per rij: de entiteit is de laadtoestand, en daarin staan de andere — gezondheid, spanningen, stromen, temperaturen, cycli, capaciteit en elke afzonderlijke cel.",
  "to the house": "naar het huis",
  "Unit of a hand-written capacity": "Eenheid van een met de hand ingevulde capaciteit",
  "Unnamed pack": "Pakket zonder naam",
  "Until you pick the state of charge this pack is nowhere: not in Energy, not on the Home tile.":
    "Zolang je de laadtoestand niet kiest, staat dit pakket nergens: niet in Energie en niet op de tegel op Home.",
  "When the highest and lowest cells are further apart than this, the pack says “Needs balancing” and the Home tile asks for attention.":
    "Als de hoogste en de laagste cel verder uit elkaar liggen dan dit, zegt het pakket „Te balanceren” en vraagt de tegel op Home om aandacht.",
