    "Seconden, minuten of uu:mm. Leeg: gebruikt de ‘Programmaduur’.",
  "Seconds, minutes, hh:mm or the end time. Empty: uses the “Remaining time”.":
    "Seconden, minuten, uu:mm of de eindtijd. Leeg: gebruikt de ‘Resterende tijd’.",
  "started at ${partita}": "gestart om ${partita}",
  "The controls show up when cooking starts": "De knoppen verschijnen zodra het koken begint",
  "The entity_id given to services that do not name one. Empty: the cooking status.":
    "De entity_id voor services die er zelf geen noemen. Leeg: de kookstatus.",
  "The rest of the kitchen": "De rest van de keuken",
  "The temperature sensor.": "De temperatuursensor.",
  "The timer is stopped until it resumes": "De timer staat stil tot het verdergaat",
  "Time and temperature set: it only needs starting":
    "Tijd en temperatuur gekozen: alleen nog starten",
  "Total time": "Totale tijd",
  "under a minute": "minder dan een minuut",
  "What the “Cooking” entry of Appliances reads and presses. A control is an entity (button, switch, number, script) or a service with its parameters: philips_airfryer.adjust_time time=60 method=add. A button only shows up when its field is filled in, and only if it answers.":
    "Wat het item ‘Koken’ van Apparaten leest en indrukt. Een bediening is een entiteit (button, switch, number, script) of een service met zijn parameters: philips_airfryer.adjust_time time=60 method=add. Een knop verschijnt alleen als zijn veld is ingevuld, en alleen als hij antwoordt.",
  "Storage battery": "Thuisbatterij",
  "💾 Stove saved": "💾 Kachel opgeslagen",
  "A fan, a number or a select. Without it, the thermostat's fan modes are used, if it has any.":
    "Een fan, een number of een select. Zonder wordt de ventilatorstand van de thermostaat gebruikt, als die er een heeft.",
  "A gas, pellet or wood boiler: flow, return, pressure, combustion.":
    "Een gas-, pellet- of houtketel: aanvoer, retour, druk, verbranding.",
  "A number or a select, 1 to 5 or P1 to P5: on the page it becomes the dots with minus and plus.":
    "Een number of een select, 1 tot 5 of P1 tot P5: op de pagina worden het de bolletjes met min en plus.",
  "A pellet stove in a room: the flame, the power, the fan and the hopper. More than one, too.":
    "Een pelletkachel in een kamer: de vlam, het vermogen, de ventilator en de voorraadbak. Ook meer dan één.",
  "A sensor with the alarm text or a binary_sensor: when it trips, the page shows the red banner with its words.":
    "Een sensor met de alarmtekst of een binary_sensor: als die afgaat, toont de pagina de rode balk met zijn woorden.",
  "Add stove": "Kachel toevoegen",
  "An electric water heater, fed by the PV plant or not.":
    "Een elektrische boiler, al dan niet gevoed door de zonnepanelen.",
  "As a percentage or in kg, like the boiler's; or a binary_sensor that turns on when the pellet is running low.":
    "In procenten of in kg, zoals bij de ketel; of een binary_sensor die aangaat als de pellets opraken.",
  "Brazier cleaning": "Branderpot reinigen",
  "Check the stove's display.": "Kijk op het display van de kachel.",
  "Flame · Power · Pellet": "Vlam · Vermogen · Pellets",
  "For whoever has two hoppers: the page shows them side by side, Pellet 1 and Pellet 2, with the same threshold as the first.":
    "Voor wie twee voorraadbakken heeft: de pagina toont ze naast elkaar, Pellets 1 en Pellets 2, met dezelfde drempel als de eerste.",
  Ignition: "Ontsteking",
  "In alarm": "Storing",
  "Living room stove": "Kachel in de woonkamer",
  "Lower the power": "Vermogen verlagen",
  Modulating: "Modulerend",
  "No stove configured": "Geen kachel ingesteld",
  "On its own it covers nearly everything: on and off, the target, the room temperature and, if it has them, the fan modes.":
    "Op zich dekt hij bijna alles: aan en uit, de streefwaarde, de kamertemperatuur en, als hij die heeft, de ventilatorstanden.",
  "Pellet level, second hopper": "Pelletniveau, tweede voorraadbak",
  "Pellet OK": "Pellets voldoende",
  "Pellet running low": "Pellets raken op",
  "Power level": "Vermogensstand",
  "Raise the power": "Vermogen verhogen",
  "Roof collectors and a tank: the fields are the ones below.":
    "Collectoren op het dak en een voorraadvat: de velden staan hieronder.",
  "Room temperature": "Kamertemperatuur",
  "Save stove": "Kachel opslaan",
  "Shutting down": "Uitschakelen",
  "Slow the fan down": "Ventilator langzamer",
  "Speed the fan up": "Ventilator sneller",
  Stove: "Kachel",
  "Stove alarm": "Kachelalarm",
  "Stove controls": "Bediening van de kachel",
  "Stove phase": "Fase van de kachel",
  "Stove thermostat": "Thermostaat van de kachel",
  "Switch (when there is no thermostat)": "Schakelaar (als er geen thermostaat is)",
  "The stove heats the room it stands in: the page draws the flame, the power, the fan, the flue and the hopper, and gives you the buttons for on and off, the target, the power and the fan. No field is required: with just the thermostat the page already has almost everything. With more than one, add them here and the page grows a row to switch between them.":
    "De kachel verwarmt de kamer waarin hij staat: de pagina tekent de vlam, het vermogen, de ventilator, het rookkanaal en de voorraadbak, en geeft je de knoppen voor aan en uit, de streefwaarde, het vermogen en de ventilator. Geen enkel veld is verplicht: met alleen de thermostaat heeft de pagina al bijna alles. Heb je er meer, voeg ze hier toe en de pagina krijgt een rij om te wisselen.",
  "The word the stove shows on its display: ignition, working, brazier cleaning, shutdown… If the page does not know it, it shows it as it is.":
    "Het woord dat de kachel op zijn display toont: ontsteking, in bedrijf, branderpot reinigen, uitschakelen… Kent de pagina het niet, dan toont ze het zoals het is.",
  "Without it, the thermostat's own reading is used.":
    "Zonder wordt de meting van de thermostaat zelf gebruikt.",
  Working: "In bedrijf",
  "Air conditioners out of season": "Airco's buiten het seizoen",
  "Radiators out of season": "Radiatoren buiten het seizoen",
  "They show: ${periodo}. Switched on, they show anyway.":
    "Zichtbaar: ${periodo}. Aangezet verschijnen ze toch.",
  "Show them anyway": "Toch tonen",
  "🐠 The aquarium's entities": "🐠 De entiteiten van het aquarium",
  "🦎 The terrarium's entities": "🦎 De entiteiten van het terrarium",
  "🧽 Cleaning": "🧽 Schoonmaak",
  "🪣 The tank": "🪣 De bak",
  Aquariums: "Aquaria",
  "Aquariums and terrariums": "Aquaria en terraria",
  "Bowl · Litter · Aquariums · Terrariums": "Voerbak · Kattenbak · Aquaria · Terraria",
  Cats: "Katten",
  "Clean every (days)": "Schoonmaken elke (dagen)",
  "Cleaned ${giorni} days ago": "${giorni} dagen geleden schoongemaakt",
