  "Cleaned yesterday": "Gisteren schoongemaakt",
  "Cleaning due": "Schoonmaak nodig",
  Dogs: "Honden",
  "Heat lamp or heating": "Warmtelamp of verwarming",
  "Humidity too high": "Luchtvochtigheid te hoog",
  "Humidity too low": "Luchtvochtigheid te laag",
  "Last cleaning": "Laatste schoonmaak",
  Mister: "Vernevelaar",
  "Not recorded yet: tap “Done today” on the day you clean it, and from then on the card counts the days.":
    "Nog niet vastgelegd: tik op ‘Vandaag gedaan’ op de dag dat je het schoonmaakt, en vanaf dan telt de kaart de dagen.",
  "One row per entity: temperature and pH with their ideal range, the water level, the lights, the filter and the heater. Empty ranges use the defaults: 24–27 °C and pH 6.5–7.5.":
    "Eén rij per entiteit: temperatuur en pH met hun ideale bereik, het waterniveau, de lampen, het filter en de verwarming. Lege bereiken gebruiken de standaardwaarden: 24–27 °C en pH 6,5–7,5.",
  "One row per entity: warm-side and cool-side temperatures, humidity, lights, heat lamp, UVB, mister. Empty ranges use the defaults: 28–35 °C on the warm side, 22–28 °C on the cool side, humidity 40–80 %.":
    "Eén rij per entiteit: temperatuur aan de warme en de koele kant, luchtvochtigheid, lampen, warmtelamp, UVB, vernevelaar. Lege bereiken gebruiken de standaardwaarden: 28–35 °C aan de warme kant, 22–28 °C aan de koele kant, luchtvochtigheid 40–80 %.",
  "Optional: left empty, the terrarium reminds nobody to clean it. With a number the card says when it is due.":
    "Optioneel: leeg herinnert het terrarium niemand aan de schoonmaak. Met een getal zegt de kaart wanneer het tijd is.",
  "Other pet": "Ander dier",
  "Other pets": "Andere dieren",
  "Other reading": "Andere meting",
  "Reservoir level": "Niveau van het reservoir",
  "Take the ${quante} terrarium entities Home Assistant found":
    "Neem de ${quante} terrarium-entiteiten die Home Assistant heeft gevonden",
  "Temperature (cool side)": "Temperatuur (koele kant)",
  "Temperature (warm side)": "Temperatuur (warme kant)",
  Terrarium: "Terrarium",
  "Terrarium climate": "Klimaat van het terrarium",
  Terrariums: "Terraria",
  "The pets of the house: one card each, with its photo and what concerns it — the bowl, the litter box, the water, the microchip door, the collar. Aquariums and terrariums too, as many as you have: each with its own entities.":
    "De huisdieren van het huis: voor elk een kaart, met foto en alles wat erbij hoort — de voerbak, de kattenbak, het water, het kattenluik met microchip, de halsband. Ook aquaria en terraria, zoveel als je hebt: elk met zijn eigen entiteiten.",
