  "Front door": "Voordeur",
  "It fills itself with every light of the source dashboard: a light added there shows up here too.":
    "Vult zichzelf met alle lampen van het bronoverzicht: een lamp die daar wordt toegevoegd, verschijnt ook hier.",
  "My page": "Mijn pagina",
