  "The page takes its temperature and suggested controls from here":
    "De pagina haalt hier de temperatuur en de voorgestelde bediening vandaan",
  "Your own controls": "Je eigen bediening",
  "Heating · Cooling": "Verwarmen · Koelen",
  "It fills itself with the source dashboard's climate, split into the Cooling and Heating tabs like the Climate section: air conditioners in cooling, radiators and thermostats in heating, heat pumps in both.":
    "Vult zichzelf met het klimaat van het bronoverzicht, verdeeld over de tabbladen Koelen en Verwarmen zoals in de sectie Klimaat: airco's bij koelen, radiatoren en thermostaten bij verwarmen, warmtepompen in allebei.",
  "Opens on": "Opent op",
  "Page type": "Paginatype",
  "Shown on the tab at the top": "Staat op het tabblad bovenaan",
  "The wall tablet's panel. Choose the pages — the tabs at the top — and what each one holds. On the tablet, holding the clock for two seconds brings you back here.":
    "Het paneel van de wandtablet. Kies de pagina's – de tabbladen bovenaan – en wat erin staat. Op de tablet brengt twee seconden de klok ingedrukt houden je hier terug.",
  "All blinds": "Alle rolluiken",
