    "Hoeveel plekken en hoe groot. Staand wisselen kolommen en rijen",
  "It fills itself with every blind of the source dashboard: up, stop and down for each one.":
    "Vult zich vanzelf met alle rolluiken van het brondashboard: omhoog, stop en omlaag voor elk.",
  "Lights off": "Lichten uit",
