  Right: "Rechts",
  "Side menu": "Zijmenu",
  "Start and shutdown": "Start en afsluiten",
  "Stop (optional)": "Stop (optioneel)",
  "The pages in a column of big buttons on the left, like on control-room panels. Landscape only: in portrait and on small screens the tabs at the top stay":
    "De pagina's in een kolom met grote knoppen links, zoals op regiepanelen. Alleen liggend: staand en op kleine schermen blijven de tabbladen bovenaan",
  Zoom: "Zoom",
  "☀️ Panel": "☀️ Paneel",
  "🎛️ Controls": "🎛️ Bediening",
  "🔁 Circuit": "🔁 Zonnecircuit",
  "🛢️ Tank": "🛢️ Boilervat",
  "Power sensor (sensor, W)": "Vermogenssensor (sensor, W)",
  "Pressure sensor (sensor, bar)": "Druksensor (sensor, bar)",
  "Solar pump (state)": "Zonnepomp (status)",
  "Switch to turn on and off (switch or input_boolean)":
    "Schakelaar om aan en uit te zetten (switch of input_boolean)",
  "Tank bottom": "Boilervat onder",
  "Tank top": "Boilervat boven",
  "Tells whether the pump runs (binary_sensor or switch): makes the light flow in the pipes":
    "Geeft aan of de pomp draait (binary_sensor of switch): laat het licht door de leidingen lopen",
  "Temperature sensor (sensor, °C)": "Temperatuursensor (sensor, °C)",
  "Temperature sensor (sensor, °C): panel minus tank":
    "Temperatuursensor (sensor, °C): paneel min boilervat",
  "Valve (valve) or switch (switch); empty uses valve.chiave_solare_termico":
    "Klep (valve) of schakelaar (switch); leeg gebruikt valve.chiave_solare_termico",
  "Valve with a position (cover): open above zero": "Klep met positie (cover): open boven nul",
  Command: "Commando",
  "▲ command": "▲-commando",
  "▼ command": "▼-commando",
  "Start command": "Startcommando",
  "Mute command": "Dempcommando",
  "Stop command": "Stopcommando",
  "The dashboard doesn't know the arrows of ${nome}: the remote shows among the commands as an on/off button. Its commands go in «Other commands», as remote.name:command.":
    "Het dashboard kent de pijlen van ${nome} niet: de afstandsbediening verschijnt bij de commando's als aan/uit-knop. Haar commando's voeg je toe bij «Andere commando's», als remote.name:command.",
  "Home Assistant doesn't say which integration this remote belongs to: it shows among the commands as an on/off button. Its commands go in «Other commands», as remote.name:command.":
    "Home Assistant zegt niet bij welke integratie deze afstandsbediening hoort: ze verschijnt bij de commando's als aan/uit-knop. Haar commando's voeg je toe bij «Andere commando's», als remote.name:command.",
  "Device (optional)": "Apparaat (optioneel)",
  "Remote device": "Apparaat van de afstandsbediening",
  "Optional: the «device» of remote.send_command":
    "Optioneel: het «device» van remote.send_command",
  "The live picture on the left, arrows and zoom on the right, presets below. Each button presses an entity already in Home Assistant: a camera button, a script with onvif.ptz, or a remote with the command to send. A button without an entity stays off.":
    "Het livebeeld links, de pijlen en zoom rechts, de presets eronder. Elke knop drukt op een entiteit die al in Home Assistant bestaat: een knop van de camera, een script met onvif.ptz, of een afstandsbediening (remote) met het commando om te sturen. Een knop zonder entiteit blijft uit.",
  "Read level (optional)": "Gelezen niveau (optioneel)",
  "Each channel is an upright fader with its mute: a player's volume, or a number (number, input_number) like a mixer's dB. A sensor becomes a meter you look at; a remote gets ▲ / ▼ and mute, each with its own command (remote.send_command). Mute is the player's own, a switch (on means muted), a remote or a button to press.":
    "Elk kanaal is een staande fader met zijn demping: het volume van een speler, of een getal (number, input_number) zoals de dB van een mengpaneel. Een sensor wordt een meter om af te lezen; een afstandsbediening (remote) krijgt ▲ / ▼ en dempen, elk met een eigen commando (remote.send_command). Dempen is dat van de speler, een schakelaar (aan betekent gedempt), een afstandsbediening of een knop om in te drukken.",
  "What the integration publishes next to the player — a TV's power switch, the input dropdown, a scene: button.*, select.*, switch.* entities (plus input_*, script.*, scene.*). A remote.* turns on and off; written remote.name:command (for example remote.amp:volume_up) it sends that command. They appear on the card under the playback controls.":
    "Wat de integratie naast de speler publiceert — de aan/uit-schakelaar van een tv, de bronkeuze, een scène: entiteiten button.*, select.*, switch.* (plus input_*, script.*, scene.*). Een afstandsbediening remote.* gaat aan en uit; geschreven als remote.name:command (bijvoorbeeld remote.amp:volume_up) stuurt ze dat commando. Ze verschijnen op de kaart onder de afspeelknoppen.",
  "Scale: to": "Schaal: tot",
  "Scale: from": "Schaal: van",
  "A button.*, select.*, switch.* or remote.* entity is required (also remote.name:command) — or input_button, input_select, input_boolean, script, scene.":
    "Een entiteit button.*, select.*, switch.* of remote.* is nodig (ook remote.name:command) — of input_button, input_select, input_boolean, script, scene.",
  "A sensor with the level": "Een sensor met het niveau",
  "Empty: turns on": "Leeg: zet aan",
  "Empty: turns off": "Leeg: zet uit",
  "${inserite} of ${tutte} armed": "${inserite} van ${tutte} ingeschakeld",
  "Add a command": "Opdracht toevoegen",
  "Add a partition": "Partitie toevoegen",
  "Add a reading": "Meting toevoegen",
  "Alarm · ${quante} areas": "Alarm · ${quante} gebieden",
  "Alarm partitions": "Alarmpartities",
  "Buttons next to the readings: locks (lock and unlock), scripts, buttons, scenes, switches, blinds. A remote turns on and off; written remote.name:command it sends that command.":
    "Knoppen naast de metingen: sloten (vergrendelen en ontgrendelen), scripts, knoppen, scènes, schakelaars, rolluiken. Een afstandsbediening (remote) gaat aan en uit; geschreven als remote.name:command stuurt ze die opdracht.",
  "Empty: all the ones from the dashboard's Security section":
    "Leeg: alle uit de sectie Beveiliging van het dashboard",
  "Intercom / camera": "Deurintercom / camera",
  "Leaving and who is home": "Vertrek en wie er thuis is",
  "All clear": "Alles in orde",
  "Open doors": "Open deuren",
  "Open doors and windows": "Open deuren en ramen",
  "since ${ora}": "sinds ${ora}",
  "The entries declared in the Security section": "De toegangen opgegeven in de sectie Beveiliging",
  "The ones chosen here, in this order: each with its state and its buttons, the ones its panel accepts":
    "De hier gekozen, in deze volgorde: elk met zijn status en zijn knoppen, die zijn centrale accepteert",
  "Under the alarm, each with its value: doors and windows (binary_sensor), sensors, locks, blinds. Two or more doors or windows become a single count, «Open windows: 2»; a tap lists them.":
    "Onder het alarm, elk met zijn waarde: deuren en ramen (binary_sensor), sensoren, sloten, rolluiken. Twee of meer deuren of ramen worden één telling, «Open ramen: 2»; een tik toont ze.",
  "Water!": "Lekkage!",
  "Next to the people": "Naast de personen",
  "No extra reading: the row says whether it is up or down, nothing else.":
    "Geen extra metingen: de rij zegt alleen of het aan of uit staat.",
  Nothing: "Niets",
  "The sensors that tell more about this device than “up” and “down” — ping latency, packet loss, uptime, the last time it was seen: sensor.*, binary_sensor.*, number.* entities. They show under its row on the MiniPC page, with their own name and unit.":
    "De sensoren die meer over dit apparaat vertellen dan „aan” en „uit” — pinglatentie, pakketverlies, uptime, wanneer het voor het laatst gezien is: entiteiten sensor.*, binary_sensor.*, number.*. Ze verschijnen onder zijn rij op de MiniPC-pagina, met hun eigen naam en eenheid.",
  "Classic bell": "Klassieke bel",
  Ding: "Ding",
  "Ding dong": "Ding-dong",
