  "Take out: ${r.name}": "Buitenzetten: ${r.name}",
  "The alarm has been triggered.": "Het alarm is afgegaan.",
  "The alarm is going off": "Het alarm gaat af",
  "the car": "de auto",
  "The house assistant watches the house for you and tells you the most important thing to do right now: lights left on in an empty house, a window open with the heating on, rain on its way, the laundry done, spare solar power. It learns from what you dismiss, and remembers it for the whole household. On a computer or tablet it sits to the right of the people, on a phone below them.":
    "De huisassistent houdt het huis voor je in de gaten en vertelt wat nu het belangrijkst is: lampen aan in een leeg huis, een raam open terwijl de verwarming aanstaat, regen op komst, de was klaar, zonnestroom over. Hij leert van wat je wegklikt en onthoudt het voor het hele huishouden. Op computer en tablet staat hij rechts van de personen, op de telefoon eronder.",
  "The house is drawing ${kw} kW from the grid": "Het huis neemt ${kw} kW van het net",
  "The house is empty and ${nomi(aperte, l)} is unlocked":
    "Het huis is leeg en ${nomi(aperte, l)} is niet op slot",
  "The leak sensor is wet: shall I close the valve?":
    "De lekmelder is nat: zal ik de klep dichtdraaien?",
  "The leak sensor is wet.": "De lekmelder is nat.",
  "There are ${quanti} updates to install": "Er zijn ${quanti} updates om te installeren",
  "There is an update to install": "Er is een update om te installeren",
  Tonight: "Vanavond",
  "Turn it off until someone is back?": "Uitzetten tot er iemand terug is?",
  "Turn it off?": "Uitzetten?",
  "Turn off climate": "Klimaat uitzetten",
  "Turn them off?": "Uitzetten?",
  urgent: "dringend",
