  "You're near the meter's limit.": "Je zit dicht bij de grens van de meter.",
  "You're out and ${g.name} is open": "Jullie zijn weg en ${g.name} staat open",
  "e.g. 30": "bijv. 30",
  "End-of-cycle delay under ${minuti} minutes: 0 W pauses mid-programme look like the end of the cycle.":
    "Vertraging einde cyclus onder ${minuti} minuten: pauzes van 0 W midden in het programma lijken op het einde van de cyclus.",
  "Recommended: running ${a} W, standby ${b} W, delay ${minuti} min.":
    "Aanbevolen: actief ${a} W, stand-by ${b} W, vertraging ${minuti} min.",
  "Running threshold under 1 W: a lit display is enough to show Running.":
    "Drempel actief onder 1 W: een brandend display is genoeg om Actief te tonen.",
  "Standby threshold at or above the running one: standby can never show.":
    "Stand-bydrempel gelijk aan of boven die van actief: stand-by kan nooit verschijnen.",
