  "the home did not answer": "het huis antwoordde niet",
  "The home that does it by itself: lights, climate, shutters and alerts that start when needed.":
    "Het huis dat het zelf doet: licht, klimaat, rolluiken en meldingen die starten wanneer het moet.",
  "The home's automations": "De automatiseringen van het huis",
  "The list and saving go through the GdAHome add-on: it is not here.":
    "De lijst en het bewaren lopen via de add-on GdAHome: die is hier niet.",
  "the new automation": "de nieuwe automatisering",
  "then → ${allora}": "dan → ${allora}",
  "This automation lives in a Home Assistant file: here you turn it on, off and run it, and it is changed there.":
    "Deze automatisering staat in een bestand van Home Assistant: hier zet je hem aan, uit en voer je hem uit, en daar wordt hij gewijzigd.",
  "This automation uses advanced features (a choice between cases, a template, a blueprint…): here you can turn it on and off, run it, rename it and change its room. For the rest:":
    "Deze automatisering gebruikt geavanceerde functies (een keuze tussen gevallen, een sjabloon, een blueprint…): hier kun je hem aan- en uitzetten, uitvoeren, hernoemen en van kamer wisselen. Voor de rest:",
