  "waits for something to happen": "wacht tot er iets gebeurt",
  "When the apps are in the stores, you turn on Premium from the app and Automations unlock here by themselves.":
    "Als de apps in de stores staan, zet je Premium aan in de app en worden de Automatiseringen hier vanzelf ontgrendeld.",
  "You'll find it in Settings → Automations, labelled GdAHome.":
    "Je vindt hem bij Instellingen → Automatiseringen, met het label GdAHome.",
