    "🚨 Opgeslagen: het huis weet wanneer het alarm afgaat",
  "A sensor that names the zone. Empty: the house looks at which door, window or motion turned on last.":
    "Een sensor die de zone noemt. Leeg: het huis kijkt welke deur, welk raam of welke beweging als laatste aanging.",
  "at rest": "in rust",
  "Empty means “on”.": "Leeg betekent ‘on’.",
  "For the “Siren off” button in the notification and in Security.":
    "Voor de knop ‘Sirene uit’ in de melding en in Beveiliging.",
