  "The entity that says the alarm is going off: a switch, a sensor or a helper. When it reads “triggered” Security, the Home tile and the wall panel turn red, and the house sends the urgent notification.":
    "De entiteit die zegt dat het alarm afgaat: een schakelaar, een sensor of een helper. Staat die op ‘afgegaan’, dan worden Beveiliging, de Home-tegel en het wandpaneel rood en stuurt het huis de dringende melding.",
