  "Every dashboard card can have a photo or a drawing that fills it: lights, climate, blinds, cameras, rooms, quick actions. The controls stay on top, readable; on the wall the same image shows on the pages that fill themselves.":
    "Elke kaart van het dashboard kan een foto of tekening hebben die hem vult: lampen, klimaat, rolluiken, camera's, kamers, snelle acties. De bediening blijft er leesbaar bovenop; aan de muur verschijnt dezelfde afbeelding op de pagina's die zichzelf vullen.",
