  "change it in More settings › Weather": "wijzigen via Meer instellingen › Weer",
  "Choose the weather entity in ⚙️ Config › On the wall › More settings › Weather, or add a weather integration in Home Assistant.":
    "Kies de weerentiteit in ⚙️ Config › Aan de muur › Meer instellingen › Weer, of voeg een weerintegratie toe in Home Assistant.",
  "Choose the weather entity in More settings › Weather, or add a weather integration in Home Assistant":
    "Kies de weerentiteit in Meer instellingen › Weer, of voeg een weerintegratie toe in Home Assistant",
  "Forecast on its way…": "Verwachting onderweg…",
  "Full-page weather: what it's like now, big, with feels-like, humidity, wind and pressure, then the coming hours and days. It uses the same weather the tablet shows at the top and on the rest screen.":
    "Het weer op een hele pagina: hoe het nu is, groot, met gevoelstemperatuur, luchtvochtigheid, wind en luchtdruk, daarna de komende uren en dagen. Het gebruikt hetzelfde weer dat de tablet bovenaan en op het rustscherm toont.",
