  "At a glance: one page with the weather and big tiles. Each tile opens its data in a popup — the solar flow, live cameras, alarm buttons — and the gate opens with one tap.": "In één oogopslag: één pagina met het weer en grote tegels. Elke tegel opent zijn gegevens in een pop-up — de zonnestroom, live camera's, alarmknoppen — en het hek gaat open met één tik.",
