  "Hockey team": "IJshockeyteam",
  "overtime": "verlenging",
  "shootout": "shoot-out",
  "The Sports page: your football or hockey team, Formula 1 and MotoGP, with results, upcoming matches and races, and standings. On Home the tile shows what matters now: the match being played, today's match, the last podium. Results are fetched by the add-on from public sources, only for signed-in users.": "De Sportpagina: je voetbal- of ijshockeyteam, Formule 1 en MotoGP, met uitslagen, komende wedstrijden en races, en standen. Op Home toont de tegel wat nu telt: de wedstrijd die bezig is, die van vandaag, het laatste podium. De add-on haalt de uitslagen uit openbare bronnen, alleen voor aangemelde gebruikers.",
  "The team's games, results (live too) and its place in its conference are shown. Italian leagues are not available: they have no public data source.": "Je ziet de wedstrijden van het team, de uitslagen (ook live) en de plaats in de conference. Italiaanse competities zijn er niet: ze hebben geen openbare gegevensbron.",
  "✓ Sent: you should hear it now.": "✓ Verzonden: je zou het nu moeten horen.",
  "A sentence on the chosen Echos.": "Een zin op de gekozen Echo's.",
  "Announcement": "Aankondiging",
  "Announcement: a chime, then the voice. Voice: the voice only.": "Aankondiging: eerst een geluid, dan de stem. Stem: alleen de stem.",
  "Have the Echos say the notifications": "Laat de Echo's de meldingen uitspreken",
  "How it says it": "Hoe hij het zegt",
  "Install the «Alexa Media Player» integration from HACS and sign in with your Amazon account: the Echos show up here by themselves.": "Installeer de integratie «Alexa Media Player» via HACS en meld je aan met je Amazon-account: de Echo's verschijnen hier vanzelf.",
  "No Echo in Home Assistant": "Geen Echo in Home Assistant",
  "Notifications reach the phones; this way the Echos at home say them too, for whoever is home with their hands full. It applies to the whole home.": "Meldingen gaan naar de telefoons; zo zeggen de Echo's thuis ze ook, voor wie thuis is met volle handen. Geldt voor het hele huis.",
  "offline": "uitgeschakeld",
