  "Strava is here: it has its own tab on the Health page, with this week, the last twelve weeks, statistics and latest activities.": "Strava is er: het heeft een eigen tabblad op de Gezondheidspagina, met deze week, de laatste twaalf weken, statistieken en de laatste activiteiten.",
  "Systolic pressure": "Systolische druk",
  "The Health page: steps, heart rate, blood pressure, weight and sleep of the people at home, and Strava. It finds the readings among Home Assistant's sensors on its own; here you choose the goal, the names and, if needed, the sensors.": "De Gezondheidspagina: stappen, hartslag, bloeddruk, gewicht en slaap van wie er thuis woont, en Strava. Ze vindt de metingen zelf tussen de sensoren van Home Assistant; hier kies je het doel, de namen en, zo nodig, de sensoren.",
